    { key: 'gunShop', name: 'Gun Shop', at: 'gunShop' },
    { key: 'garage', name: 'Garage', at: 'garage' },
    { key: 'diner', name: 'Diner', at: 'diner' },
    { key: 'chopShop', name: 'Chop Shop', at: 'chopShop' },
